 const companions=world.workers.slice(0,2);const originalCloth=new Map(),roadCloth=new Map();for(const [i,c]of companions.entries())for(const m of c.root.getChildMeshes())if(m.material?.name.includes('waistcoat')){const original=m.material;if(!roadCloth.has(original)){const copy=original.clone((i?'Pippin ochre':'Merry forest green')+' travel waistcoat');if(copy.albedoColor)copy.albedoColor.set(...(i?[1,.78,.4]:[.45,.8,.65]));roadCloth.set(original,copy);}originalCloth.set(m,original);}const names=['ميري','بيبين'];const proxies=companions.map((c,i)=>{const m=M.CreateSphere('road friend '+i+' collision proxy',{diameter:1,segments:4},scene);m.isVisible=false;m.ellipsoid=new V(.32,.7,.32);return m;});
