 function interact(){if(weather?.active)return weather.interact();if(town?.active)return town.interact();const item=interactable(world.body.position);if(!item)return false;const action=item.id.slice(5);if(action==='gate'){enterBree();return true;}if(advanceRoad(road,action==='meet'?'meet':action==='join'?'join':'board',world.body.position)){if(action==='meet')message('يظهر ميري وبيبين من بين حقول الخضار. يعرفان فرودو، لكنهما لا يعرفان سرّ الخاتم. الطريق الضيق يقود الأربعة نحو الغابة.');if(action==='join')message('يتوقف فرودو: وقع حوافر غريب يقترب. إلى الجذور على يسار الدرب؛ ابقَ داخل الفجوة حتى يمرّ الفارس.');if(action==='board'){crossing=0;world.body.position.set(10,1.03,24.8);message('يفكّ سام حبل الرسو، ويدفع ميري العبّارة بعمودها. بقي الخاتم مخفيًا مع فرودو.');}cover=0;onChange(roadObjective(road));}return true;}
